package mavlink

import (
	"bytes"
	"encoding/hex"
	"math"
	"testing"
)

// These frames were generated by the vendored C library in core/third_party/mavlink,
// so they check the CRC extras and field offsets against the real definitions.
const (
	goldenHeartbeat  = "fd090000000101000000110000000203d10403fccd"
	goldenSysStatus  = "fd1f0000010101010000238000002380000003000000f4013831ffff00000000000000000000000057b29d"
	goldenGPSRaw     = "fd1e000002010118000015cd5b070000000094feebea12cfe85840e908007900c80052032823030e0da3"
	goldenGlobalPos  = "fd1c0000030101210000881300000001ecea88d1e85860370900204e00002c0170feceffbe146353"
	goldenNamedValue = "fd1100000401bffb0000581b00000000803e54525553545f4e4156c666"
	goldenStatusText = "fd2700000501bffd0000044155544f4e4f4d5920534146455f4c414e443a20686172647761726520756e747275737465640365"
	goldenRequestInt = "fd0400000601013300000300febe6cf7"
	goldenMissionAck = "fd0200000701012f0000febee2e7"
	goldenCount      = "fd04000008febe2c000006000101defa"
	goldenItemInt    = "fd25000009febe4900000000000000000000000000000000000094feebea12cfe8580000a441020010000101030001ec57"
)

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func parseSingle(t *testing.T, s string) Frame {
	t.Helper()
	frames := Parse(mustHex(t, s))
	if len(frames) != 1 {
		t.Fatalf("got %d frames, want 1", len(frames))
	}
	return frames[0]
}

func near(a, b float64) bool { return math.Abs(a-b) < 1e-6 }

func TestDecodeGoldenFrames(t *testing.T) {
	f := parseSingle(t, goldenHeartbeat)
	hb := DecodeHeartbeat(f.Payload)
	if f.MsgID != MsgHeartbeat || f.SysID != 1 || f.CompID != 1 {
		t.Errorf("heartbeat header: %+v", f)
	}
	if hb != (Heartbeat{CustomMode: 17, Type: 2, Autopilot: 3, BaseMode: 209}) {
		t.Errorf("heartbeat: %+v", hb)
	}

	ss := DecodeSysStatus(parseSingle(t, goldenSysStatus).Payload)
	if ss.SensorsPresent != 0x8023 || ss.SensorsHealth != 3 || ss.BatteryRemaining != 87 {
		t.Errorf("sys_status: %+v", ss)
	}

	gps := DecodeGPSRawInt(parseSingle(t, goldenGPSRaw).Payload)
	if !near(gps.Lat, -35.363262) || !near(gps.Lon, 149.165237) || gps.FixType != 3 || gps.Satellites != 14 {
		t.Errorf("gps_raw: %+v", gps)
	}

	pos := DecodeGlobalPositionInt(parseSingle(t, goldenGlobalPos).Payload)
	if !near(pos.Lat, -35.3632) || !near(pos.Lon, 149.1653) || pos.RelativeAltM != 20 ||
		pos.VNorth != 3 || pos.VEast != -4 || pos.HeadingCdeg != 5310 {
		t.Errorf("global_pos: %+v", pos)
	}

	f = parseSingle(t, goldenNamedValue)
	name, value := DecodeNamedValueFloat(f.Payload)
	if name != "TRUST_NAV" || value != 0.25 || f.CompID != 191 {
		t.Errorf("named_value: %s %f comp %d", name, value, f.CompID)
	}

	severity, text := DecodeStatusText(parseSingle(t, goldenStatusText).Payload)
	if severity != 4 || text != "AUTONOMY SAFE_LAND: hardware untrusted" {
		t.Errorf("statustext: %d %q", severity, text)
	}

	seq, ts, tc, mt := DecodeMissionRequest(parseSingle(t, goldenRequestInt).Payload)
	if seq != 3 || ts != 254 || tc != 190 || mt != 0 {
		t.Errorf("mission_request_int: %d %d %d %d", seq, ts, tc, mt)
	}

	// Trailing zeros are trimmed on the wire here, so this also covers re-padding.
	ts, tc, result, mt := DecodeMissionAck(parseSingle(t, goldenMissionAck).Payload)
	if ts != 254 || tc != 190 || result != MissionAccepted || mt != MissionTypeMission {
		t.Errorf("mission_ack: %d %d %d %d", ts, tc, result, mt)
	}
}

func TestEncodeMatchesGolden(t *testing.T) {
	got := Encode(8, 254, 190, MsgMissionCount, PackMissionCount(1, 1, 6))
	if want := mustHex(t, goldenCount); !bytes.Equal(got, want) {
		t.Errorf("mission_count\n got %x\nwant %x", got, want)
	}

	item := MissionItem{Command: CmdNavWaypoint, Frame: FrameGlobalRelativeAlt, Lat: -35.363262, Lon: 149.165237, AltM: 20.5}
	got = Encode(9, 254, 190, MsgMissionItemInt, PackMissionItemInt(1, 1, 2, item))
	if want := mustHex(t, goldenItemInt); !bytes.Equal(got, want) {
		t.Errorf("mission_item_int\n got %x\nwant %x", got, want)
	}
}

func TestParseToleratesBadInput(t *testing.T) {
	good := mustHex(t, goldenHeartbeat)

	corrupt := bytes.Clone(good)
	corrupt[12] ^= 0xFF
	if frames := Parse(corrupt); len(frames) != 0 {
		t.Errorf("corrupt frame accepted: %+v", frames)
	}
	if frames := Parse(good[:len(good)-3]); len(frames) != 0 {
		t.Errorf("truncated frame accepted: %+v", frames)
	}

	// Garbage, then a frame with a false start, then two real frames in one datagram.
	data := append([]byte{0x00, 0x42, magicV2, 0x05}, good...)
	data = append(data, mustHex(t, goldenNamedValue)...)
	frames := Parse(data)
	if len(frames) != 2 || frames[0].MsgID != MsgHeartbeat || frames[1].MsgID != MsgNamedValueFloat {
		t.Errorf("got %+v", frames)
	}

	// An unknown message is skipped.
	unknown := Encode(0, 1, 1, 9999, []byte{1, 2, 3})
	frames = Parse(append(unknown, good...))
	if len(frames) != 1 || frames[0].MsgID != MsgHeartbeat {
		t.Errorf("after unknown message: %+v", frames)
	}

	if frames := Parse(nil); frames != nil {
		t.Errorf("nil input: %+v", frames)
	}
}

func TestParseMavlink1(t *testing.T) {
	// A v1 heartbeat, with the CRC computed the same way v1 senders do.
	payload := PackGCSHeartbeat()
	frame := []byte{magicV1, byte(len(payload)), 7, 42, 1, MsgHeartbeat}
	frame = append(frame, payload...)
	sum := crc(frame[1:], messageInfo[MsgHeartbeat].crcExtra)
	frame = append(frame, byte(sum), byte(sum>>8))

	frames := Parse(frame)
	if len(frames) != 1 || frames[0].SysID != 42 || frames[0].MsgID != MsgHeartbeat {
		t.Fatalf("got %+v", frames)
	}
}

func TestParseSkipsSignature(t *testing.T) {
	signed := mustHex(t, goldenHeartbeat)
	signed[2] = flagSigned
	sum := crc(signed[1:len(signed)-crcLen], messageInfo[MsgHeartbeat].crcExtra)
	signed[len(signed)-2], signed[len(signed)-1] = byte(sum), byte(sum>>8)
	signed = append(signed, make([]byte, sigLen)...)

	frames := Parse(append(signed, mustHex(t, goldenNamedValue)...))
	if len(frames) != 2 {
		t.Fatalf("got %d frames, want 2", len(frames))
	}
}
